INSERT INTO feature VALUES('lsp-code-lens','editor','Code lens','language-server','partial','ordinary',NULL,'A lens over each declared name counts its references across the open documents, from the reverse use index, and resolves to the references command; a lens whose document is closed resolves to no command. A lens over each binder that hides another binding names the hidden binding, by its line, its path or `builtin`, and counts the uses the binder takes, from the shadow index, and resolves to the references command over those uses.','surface-lsp','corpus/model/identity/circle-base.gandr crates/surface-lsp/src/server/fixtures/a-shadowing-binder-shows-what-it-hides-6251.gandr',NULL,'#1116 #6251');
